    AND t.id = #{bo.id}
    AND t.line_id = #{bo.lineId}
    AND t.name LIKE CONCAT('%', #{bo.name}, '%')
    AND t.code = #{bo.code}
    AND t.station_no = #{bo.stationNo}
    AND t.station_type = #{bo.stationType}
    AND t.is_change = #{bo.isChange}
    AND t.district_code = #{bo.districtCode}
    AND t.street_code = #{bo.streetCode}
    AND t.sort_order = #{bo.sortOrder}

ORDER BY t.sort_order ASC, t.station_no ASC, t.id ASC
